export const TYPES=[{name:'BRUISER',mass:1.2,power:18,grip:7,maxHP:120,turn:1,color:0xff6236},{name:'VANDAL',mass:.94,power:21,grip:8,maxHP:98,turn:1.15,color:0x64d7d1},{name:'IRONCLAD',mass:1.55,power:15,grip:6.5,maxHP:150,turn:.86,color:0xe5bd65}];
export const RADIUS=43, DURATION=180, COUNT=12;
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const angle=(v)=>Math.atan2(Math.sin(v),Math.cos(v));
export function seeded(seed=42){return()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};}
export function makeWorld(type=0,seed=42){const rand=seeded(seed);const cars=Array.from({length:COUNT},(_,i)=>{const a=i/COUNT*Math.PI*2;const t=TYPES[i===0?type:i%3];return {id:i,type:i===0?type:i%3,x:Math.sin(a)*32,z:Math.cos(a)*32,heading:a+Math.PI,vx:0,vz:0,omega:0,hp:t.maxHP,maxHP:t.maxHP,parts:{front:100,rear:100,left:100,right:100},score:0,kills:0,contacts:0,damage:0,dead:false,target:-1,aiTimer:0,reverse:0,stuck:0,lastContact:0,hitAt:-10,wreckAt:0,throttle:0,steer:0};});return{cars,time:0,events:[],pairs:new Map(),rand,done:false};}
function hit(w,c,damage,nx,nz,other){if(c.dead)return;const f=Math.sin(c.heading)*nx+Math.cos(c.heading)*nz;const r=Math.cos(c.heading)*nx-Math.sin(c.heading)*nz;const part=f>.55?'front':f<-.55?'rear':r>0?'right':'left';const protection=part==='rear'?.55:part==='front'?1.1:.86;const d=damage*protection;c.parts[part]=clamp(c.parts[part]-d*1.4,0,100);c.hp=Math.max(0,c.hp-d);c.damage+=d;c.hitAt=w.time;c.lastContact=w.time;if(c.hp<=0){c.dead=true;c.wreckAt=w.time;if(other&&!other.dead){other.kills++;other.score+=500;}w.events.push({type:'wreck',car:c.id,by:other?.id??-1,x:c.x,z:c.z,power:25});}return d;}
function ai(w,c,dt){c.aiTimer-=dt;const speed=Math.hypot(c.vx,c.vz);c.stuck=speed<2?c.stuck+dt:0;if(c.stuck>1.8){c.reverse=1.3;c.stuck=0;}
 if(c.aiTimer<=0||!w.cars[c.target]||w.cars[c.target].dead){let best=Infinity;c.target=-1;for(const o of w.cars){if(o===c||o.dead)continue;const dist=Math.hypot(o.x-c.x,o.z-c.z);const bias=(o.id===0?1.1:1)*(1+w.rand()*.4);const cost=dist*bias+Math.abs(angle(Math.atan2(o.x-c.x,o.z-c.z)-c.heading))*3;if(cost<best){best=cost;c.target=o.id;}}c.aiTimer=.55+w.rand()*.8;}
 const target=w.cars[c.target];if(!target)return{gas:0,steer:0,brake:0,hand:0};const dist=Math.hypot(target.x-c.x,target.z-c.z);const lead=clamp(dist/35,0,.65);const desired=Math.atan2(target.x+target.vx*lead-c.x,target.z+target.vz*lead-c.z);const delta=angle(desired-c.heading);if(c.reverse>0){c.reverse-=dt;return{gas:0,brake:1,steer:-Math.sign(delta),hand:0};}return{gas:Math.abs(delta)>1.2?.52:1,brake:0,steer:clamp(delta*1.8,-1,1),hand:Math.abs(delta)>1.25&&speed>12?1:0};}
function drive(w,c,u,dt){const t=TYPES[c.type],fx=Math.sin(c.heading),fz=Math.cos(c.heading),rx=fz,rz=-fx;let forward=c.vx*fx+c.vz*fz,side=c.vx*rx+c.vz*rz;const damageFactor=.65+.35*clamp(c.parts.front/100,0,1);const throttle=c.dead?0:u.gas||0;let acc=throttle*t.power*damageFactor;if(!c.dead&&u.brake){acc-=forward>1?33:11;if(forward<-11)acc=0;}if(forward>29*damageFactor)acc=Math.min(acc,0);forward+=acc*dt;forward*=Math.exp(-(c.dead?1.6:.20)*dt);side*=Math.exp(-(u.hand?1.8:t.grip)*dt);if(u.hand)forward*=Math.exp(-.6*dt);c.vx=fx*forward+rx*side;c.vz=fz*forward+rz*side;const steering=c.dead?0:(u.steer||0);const yaw=steering*t.turn*(u.hand?1.95:1.45)*clamp(Math.abs(forward)/5,0,1)*Math.sign(forward);c.omega+=(yaw-c.omega)*(1-Math.exp(-6*dt));c.heading=angle(c.heading+c.omega*dt);c.x+=c.vx*dt;c.z+=c.vz*dt;c.throttle=throttle;c.steer=steering;
 const dist=Math.hypot(c.x,c.z),limit=RADIUS-2.45;if(dist>limit){const nx=c.x/dist,nz=c.z/dist;c.x=nx*limit;c.z=nz*limit;const v=c.vx*nx+c.vz*nz;if(v>0){c.vx-=nx*v*1.45;c.vz-=nz*v*1.45;c.omega+=clamp((fx*nz-fz*nx)*v*.07,-1.5,1.5);if(v>5&&w.time-c.hitAt>.35){hit(w,c,(v-4)*.55,nx,nz);w.events.push({type:'wall',car:c.id,x:c.x+nx,z:c.z+nz,power:v});}}}}
function collision(w,a,b){if(Math.abs(a.x-b.x)>6||Math.abs(a.z-b.z)>6)return;const axes=[[Math.cos(a.heading),-Math.sin(a.heading)],[Math.sin(a.heading),Math.cos(a.heading)],[Math.cos(b.heading),-Math.sin(b.heading)],[Math.sin(b.heading),Math.cos(b.heading)]];const dx=b.x-a.x,dz=b.z-a.z;let depth=Infinity,nx=0,nz=0;for(const [ax,az] of axes){const ra=1.08*Math.abs(ax*axes[0][0]+az*axes[0][1])+2.2*Math.abs(ax*axes[1][0]+az*axes[1][1]);const rb=1.08*Math.abs(ax*axes[2][0]+az*axes[2][1])+2.2*Math.abs(ax*axes[3][0]+az*axes[3][1]);const signed=dx*ax+dz*az,overlap=ra+rb-Math.abs(signed);if(overlap<=0)return;if(overlap<depth){depth=overlap;nx=ax*Math.sign(signed||1);nz=az*Math.sign(signed||1);}}
 const ma=1/TYPES[a.type].mass,mb=1/TYPES[b.type].mass,sum=ma+mb;a.x-=nx*(depth+.006)*ma/sum;a.z-=nz*(depth+.006)*ma/sum;b.x+=nx*(depth+.006)*mb/sum;b.z+=nz*(depth+.006)*mb/sum;const closing=(a.vx-b.vx)*nx+(a.vz-b.vz)*nz;if(closing<=0)return;const impulse=closing*1.35/sum;a.vx-=nx*impulse*ma;a.vz-=nz*impulse*ma;b.vx+=nx*impulse*mb;b.vz+=nz*impulse*mb;
 const tangent=clamp((dx*nz-dz*nx)*.18,-.8,.8);a.omega=clamp(a.omega-tangent*impulse*.12,-3,3);b.omega=clamp(b.omega+tangent*impulse*.12,-3,3);
 const key=a.id*COUNT+b.id;if(closing<3||w.time-(w.pairs.get(key)??-10)<.45)return;w.pairs.set(key,w.time);const damage=(closing-2)*.42;const da=hit(w,a,damage*TYPES[b.type].mass,nx,nz,b)||0;const db=hit(w,b,damage*TYPES[a.type].mass,-nx,-nz,a)||0;
 if(!a.dead||a.hitAt===w.time){a.score+=Math.round(db*12);a.contacts++;a.lastContact=w.time;}if(!b.dead||b.hitAt===w.time){b.score+=Math.round(da*12);b.contacts++;b.lastContact=w.time;}w.events.push({type:'impact',a:a.id,b:b.id,power:closing,x:(a.x+b.x)/2,z:(a.z+b.z)/2});
}
export function step(w,input,dt=1/60,autoplay=false){if(w.done)return;w.events=[];w.time+=dt;for(const c of w.cars)drive(w,c,c.dead?{}:c.id===0&&!autoplay?input:ai(w,c,dt),dt);for(let pass=0;pass<2;pass++)for(let i=0;i<COUNT;i++)for(let j=i+1;j<COUNT;j++)collision(w,w.cars[i],w.cars[j]);for(const c of w.cars){if(!c.dead&&w.time-c.lastContact>22){c.hp=Math.max(0,c.hp-dt*2.5);if(c.hp<=0){c.dead=true;c.wreckAt=w.time;w.events.push({type:'wreck',car:c.id,by:-1,x:c.x,z:c.z,power:20});}}}if(w.cars.filter(c=>!c.dead).length<=1||w.time>=DURATION)w.done=true;}
export function ranking(w){return [...w.cars].sort((a,b)=>Number(a.dead)-Number(b.dead)||(a.dead?b.wreckAt-a.wreckAt:b.score-a.score)||b.hp/b.maxHP-a.hp/a.maxHP);}
